// CAN_XL_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module CAN_XL_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [5:0] c_cfg_brp,
  input logic [3:0] c_cfg_tseg1,
  input logic [2:0] c_cfg_tseg2,
  input logic [1:0] c_cfg_sjw,
  input logic [5:0] c_cfg_dbrp,
  input logic [3:0] c_cfg_dtseg1,
  input logic [2:0] c_cfg_dtseg2,
  input logic [1:0] c_cfg_dsjw,
  input logic [28:0] c_acc_code,
  input logic [28:0] c_acc_mask,
  input logic [28:0] c_tx_id,
  input logic  c_tx_ide,
  input logic  c_tx_rtr,
  input logic  c_tx_xl,
  input logic [10:0] c_tx_dlc,
  input logic [7:0] c_tx_sdt,
  input logic  c_tx_sec,
  input logic [7:0] c_tx_vcid,
  input logic [31:0] c_tx_af,
  input logic  c_tx_valid,
  input logic  c_tx_abort,
  input logic [28:0] c_rx_id,
  input logic  c_rx_ide,
  input logic  c_rx_rtr,
  input logic  c_rx_xl,
  input logic [10:0] c_rx_dlc,
  input logic [7:0] c_rx_sdt,
  input logic  c_rx_sec,
  input logic [7:0] c_rx_vcid,
  input logic  c_rx_trunc,
  input logic [31:0] c_rx_af,
  input logic  c_tx_ready,
  input logic [8:0] c_tec,
  input logic [7:0] c_rec,
  input logic  c_err_passive,
  input logic  c_bus_off,
  input logic  c_tx_done,
  input logic  c_tx_aborted,
  input logic  c_tx_rejected,
  input logic  c_rx_valid,
  input logic  c_arb_lost,
  input logic  c_err_bit,
  input logic  c_err_stuff,
  input logic  c_err_crc,
  input logic  c_err_form,
  input logic  c_err_ack,
  input logic  c_pexc,
  input logic  c_hb_wen,
  input logic [31:0] c_hb_wdata,
  input logic [31:0] c_hb_rdata
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 33;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:32];          // model of every stored word
  logic [12:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_tx_done) m_set[0] = 1'b1;
    if (c_tx_aborted) m_set[1] = 1'b1;
    if (c_tx_rejected) m_set[2] = 1'b1;
    if (c_rx_valid) m_set[3] = 1'b1;
    if (c_arb_lost) m_set[4] = 1'b1;
    if (c_err_bit) m_set[5] = 1'b1;
    if (c_err_stuff) m_set[6] = 1'b1;
    if (c_err_crc) m_set[7] = 1'b1;
    if (c_err_form) m_set[8] = 1'b1;
    if (c_err_ack) m_set[9] = 1'b1;
    if (c_pexc) m_set[10] = 1'b1;
    if (c_err_passive) m_set[11] = 1'b1;
    if (c_bus_off) m_set[12] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h2941;
      m_w[6] <= 32'h4C0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_w[26] <= 32'h0;
      m_w[27] <= 32'h0;
      m_w[28] <= 32'h0;
      m_w[29] <= 32'h0;
      m_w[30] <= 32'h0;
      m_w[31] <= 32'h0;
      m_w[32] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1FFF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7FFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h7FFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 12) ? PWDATA & m_be & 32'h3 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h584C0100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return 0;
      13: return 32'(c_hb_rdata);
      14: return 32'(c_hb_rdata);
      15: return 32'(c_hb_rdata);
      16: return 32'(c_hb_rdata);
      17: return 32'(c_hb_rdata);
      18: return 32'(c_hb_rdata);
      19: return 32'(c_hb_rdata);
      20: return 32'(c_hb_rdata);
      21: return 32'(c_hb_rdata);
      22: return 32'(c_hb_rdata);
      23: return 32'(c_hb_rdata);
      24: return 32'(c_hb_rdata);
      25: return 32'(c_hb_rdata);
      26: return 32'(c_hb_rdata);
      27: return 32'(c_hb_rdata);
      28: return 32'(c_hb_rdata);
      29: return (32'(c_rx_id) << 0) | (32'(c_rx_ide) << 29) | (32'(c_rx_rtr) << 30) | (32'(c_rx_xl) << 31);
      30: return (32'(c_rx_dlc) << 0) | (32'(c_rx_sdt) << 11) | (32'(c_rx_sec) << 19) | (32'(c_rx_vcid) << 20) | (32'(c_rx_trunc) << 28);
      31: return (32'(c_rx_af) << 0);
      32: return (32'(c_tx_ready) << 0) | (32'(c_tec) << 1) | (32'(c_rec) << 10) | (32'(c_err_passive) << 18) | (32'(c_bus_off) << 19);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  wire        m_bus_partial = PWRITE && PSTRB != 4'hF && m_map && (m_idx == 13 || m_idx == 14 || m_idx == 15 || m_idx == 16 || m_idx == 17 || m_idx == 18 || m_idx == 19 || m_idx == 20 || m_idx == 21 || m_idx == 22 || m_idx == 23 || m_idx == 24 || m_idx == 25 || m_idx == 26 || m_idx == 27 || m_idx == 28);   // dropped with PSLVERR
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == (!m_map || m_bus_partial))
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][12:0] & m_w[2][12:0]))
  `SVA_INV(a_core_cfg_brp, c_cfg_brp == m_w[5][5:0])
  `SVA_INV(a_core_cfg_tseg1, c_cfg_tseg1 == m_w[5][9:6])
  `SVA_INV(a_core_cfg_tseg2, c_cfg_tseg2 == m_w[5][12:10])
  `SVA_INV(a_core_cfg_sjw, c_cfg_sjw == m_w[5][14:13])
  `SVA_INV(a_core_cfg_dbrp, c_cfg_dbrp == m_w[6][5:0])
  `SVA_INV(a_core_cfg_dtseg1, c_cfg_dtseg1 == m_w[6][9:6])
  `SVA_INV(a_core_cfg_dtseg2, c_cfg_dtseg2 == m_w[6][12:10])
  `SVA_INV(a_core_cfg_dsjw, c_cfg_dsjw == m_w[6][14:13])
  `SVA_INV(a_core_acc_code, c_acc_code == m_w[7][28:0])
  `SVA_INV(a_core_acc_mask, c_acc_mask == m_w[8][28:0])
  `SVA_INV(a_core_tx_id, c_tx_id == m_w[9][28:0])
  `SVA_INV(a_core_tx_ide, c_tx_ide == m_w[9][29:29])
  `SVA_INV(a_core_tx_rtr, c_tx_rtr == m_w[9][30:30])
  `SVA_INV(a_core_tx_xl, c_tx_xl == m_w[9][31:31])
  `SVA_INV(a_core_tx_dlc, c_tx_dlc == m_w[10][10:0])
  `SVA_INV(a_core_tx_sdt, c_tx_sdt == m_w[10][18:11])
  `SVA_INV(a_core_tx_sec, c_tx_sec == m_w[10][19:19])
  `SVA_INV(a_core_tx_vcid, c_tx_vcid == m_w[10][27:20])
  `SVA_INV(a_core_tx_af, c_tx_af == m_w[11][31:0])
  `SVA_INV(a_core_tx_valid, c_tx_valid == m_pulse_CMD[0])
  `SVA_INV(a_core_tx_abort, c_tx_abort == m_pulse_CMD[1])
  wire m_bus_wr_BUF = m_wr && m_map && PSTRB == 4'hF && (m_idx == 13 || m_idx == 14 || m_idx == 15 || m_idx == 16 || m_idx == 17 || m_idx == 18 || m_idx == 19 || m_idx == 20 || m_idx == 21 || m_idx == 22 || m_idx == 23 || m_idx == 24 || m_idx == 25 || m_idx == 26 || m_idx == 27 || m_idx == 28);
  `SVA_INV(a_core_hb_wen, c_hb_wen == m_bus_wr_BUF)
  `SVA_IMP(a_core_hb_waddr_hb_wdata, m_bus_wr_BUF, int'(u_core.hb_waddr) == (m_idx == 13 ? 0 : m_idx == 14 ? 1 : m_idx == 15 ? 2 : m_idx == 16 ? 3 : m_idx == 17 ? 4 : m_idx == 18 ? 5 : m_idx == 19 ? 6 : m_idx == 20 ? 7 : m_idx == 21 ? 8 : m_idx == 22 ? 9 : m_idx == 23 ? 10 : m_idx == 24 ? 11 : m_idx == 25 ? 12 : m_idx == 26 ? 13 : m_idx == 27 ? 14 : m_idx == 28 ? 15 : 0) && c_hb_wdata == PWDATA[31:0])
  wire m_bus_rd_BUF = m_rd && m_map && (m_idx == 13 || m_idx == 14 || m_idx == 15 || m_idx == 16 || m_idx == 17 || m_idx == 18 || m_idx == 19 || m_idx == 20 || m_idx == 21 || m_idx == 22 || m_idx == 23 || m_idx == 24 || m_idx == 25 || m_idx == 26 || m_idx == 27 || m_idx == 28);
  `SVA_INV(a_core_hb_raddr, int'(u_core.hb_raddr) == (m_bus_rd_BUF ? (m_idx == 13 ? 0 : m_idx == 14 ? 1 : m_idx == 15 ? 2 : m_idx == 16 ? 3 : m_idx == 17 ? 4 : m_idx == 18 ? 5 : m_idx == 19 ? 6 : m_idx == 20 ? 7 : m_idx == 21 ? 8 : m_idx == 22 ? 9 : m_idx == 23 ? 10 : m_idx == 24 ? 11 : m_idx == 25 ? 12 : m_idx == 26 ? 13 : m_idx == 27 ? 14 : m_idx == 28 ? 15 : 0) : 0))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_brp == 6'h1 && c_cfg_tseg1 == 4'h5 && c_cfg_tseg2 == 3'h2 && c_cfg_sjw == 2'h1 && c_cfg_dbrp == 6'h0 && c_cfg_dtseg1 == 4'h3 && c_cfg_dtseg2 == 3'h1 && c_cfg_dsjw == 2'h0 && c_acc_code == 29'h0 && c_acc_mask == 29'h0 && c_tx_id == 29'h0 && c_tx_ide == 1'h0 && c_tx_rtr == 1'h0 && c_tx_xl == 1'h0 && c_tx_dlc == 11'h0 && c_tx_sdt == 8'h0 && c_tx_sec == 1'h0 && c_tx_vcid == 8'h0 && c_tx_af == 32'h0 && c_tx_valid == 1'h0 && c_tx_abort == 1'h0 && !c_hb_wen)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_NBTR, m_rd && m_map && m_idx == 5)
  `FC(wr_NBTR, m_wr && m_map && m_idx == 5)
  `FC(rd_DBTR, m_rd && m_map && m_idx == 6)
  `FC(wr_DBTR, m_wr && m_map && m_idx == 6)
  `FC(rd_ACC_CODE, m_rd && m_map && m_idx == 7)
  `FC(wr_ACC_CODE, m_wr && m_map && m_idx == 7)
  `FC(rd_ACC_MASK, m_rd && m_map && m_idx == 8)
  `FC(wr_ACC_MASK, m_wr && m_map && m_idx == 8)
  `FC(rd_TX_ID, m_rd && m_map && m_idx == 9)
  `FC(wr_TX_ID, m_wr && m_map && m_idx == 9)
  `FC(rd_TX_CTRL, m_rd && m_map && m_idx == 10)
  `FC(wr_TX_CTRL, m_wr && m_map && m_idx == 10)
  `FC(rd_TX_AF, m_rd && m_map && m_idx == 11)
  `FC(wr_TX_AF, m_wr && m_map && m_idx == 11)
  `FC(rd_CMD, m_rd && m_map && m_idx == 12)
  `FC(wr_CMD, m_wr && m_map && m_idx == 12)
  `FC(rd_BUF0, m_rd && m_map && m_idx == 13)
  `FC(wr_BUF0, m_wr && m_map && m_idx == 13)
  `FC(rd_BUF1, m_rd && m_map && m_idx == 14)
  `FC(wr_BUF1, m_wr && m_map && m_idx == 14)
  `FC(rd_BUF2, m_rd && m_map && m_idx == 15)
  `FC(wr_BUF2, m_wr && m_map && m_idx == 15)
  `FC(rd_BUF3, m_rd && m_map && m_idx == 16)
  `FC(wr_BUF3, m_wr && m_map && m_idx == 16)
  `FC(rd_BUF4, m_rd && m_map && m_idx == 17)
  `FC(wr_BUF4, m_wr && m_map && m_idx == 17)
  `FC(rd_BUF5, m_rd && m_map && m_idx == 18)
  `FC(wr_BUF5, m_wr && m_map && m_idx == 18)
  `FC(rd_BUF6, m_rd && m_map && m_idx == 19)
  `FC(wr_BUF6, m_wr && m_map && m_idx == 19)
  `FC(rd_BUF7, m_rd && m_map && m_idx == 20)
  `FC(wr_BUF7, m_wr && m_map && m_idx == 20)
  `FC(rd_BUF8, m_rd && m_map && m_idx == 21)
  `FC(wr_BUF8, m_wr && m_map && m_idx == 21)
  `FC(rd_BUF9, m_rd && m_map && m_idx == 22)
  `FC(wr_BUF9, m_wr && m_map && m_idx == 22)
  `FC(rd_BUF10, m_rd && m_map && m_idx == 23)
  `FC(wr_BUF10, m_wr && m_map && m_idx == 23)
  `FC(rd_BUF11, m_rd && m_map && m_idx == 24)
  `FC(wr_BUF11, m_wr && m_map && m_idx == 24)
  `FC(rd_BUF12, m_rd && m_map && m_idx == 25)
  `FC(wr_BUF12, m_wr && m_map && m_idx == 25)
  `FC(rd_BUF13, m_rd && m_map && m_idx == 26)
  `FC(wr_BUF13, m_wr && m_map && m_idx == 26)
  `FC(rd_BUF14, m_rd && m_map && m_idx == 27)
  `FC(wr_BUF14, m_wr && m_map && m_idx == 27)
  `FC(rd_BUF15, m_rd && m_map && m_idx == 28)
  `FC(wr_BUF15, m_wr && m_map && m_idx == 28)
  `FC(rd_RX_ID, m_rd && m_map && m_idx == 29)
  `FC(wr_RX_ID, m_wr && m_map && m_idx == 29)
  `FC(rd_RX_CTRL, m_rd && m_map && m_idx == 30)
  `FC(wr_RX_CTRL, m_wr && m_map && m_idx == 30)
  `FC(rd_RX_AF, m_rd && m_map && m_idx == 31)
  `FC(wr_RX_AF, m_wr && m_map && m_idx == 31)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 32)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 32)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_SENT_set, m_set[0])
  `FC(irq_SENT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_SENT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_SENT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ABORTED_set, m_set[1])
  `FC(irq_ABORTED_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ABORTED_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ABORTED_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_REFUSED_set, m_set[2])
  `FC(irq_REFUSED_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_REFUSED_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_REFUSED_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_RX_set, m_set[3])
  `FC(irq_RX_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_RX_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_RX_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ARB_LOST_set, m_set[4])
  `FC(irq_ARB_LOST_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ARB_LOST_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ARB_LOST_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_ERR_BIT_set, m_set[5])
  `FC(irq_ERR_BIT_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_ERR_BIT_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_ERR_BIT_drives_pin, m_w[1][5] && m_w[2][5] && irq)
